async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let body={};try{body=await response.json();}catch{}if(!response.ok)throw new Error(body.error||'The request could not be completed.');return body;}
async function loadQuestionnaireReports(){if(!currentUser||currentUser.role!=="Trainer")return;const route=state.route,reports={};await Promise.all((state.questionnaires||[]).filter(q=>q.ownerId===currentUser.id).map(async q=>{try{reports[q.id]=(await api(`/api/questionnaires/${q.id}/responses`)).responses||[]}catch{reports[q.id]=[]}}));if(state.route===route){state.questionnaireReports=reports;render();}}
async function restoreWorkspace(user){currentUser=user;const result=await api('/api/workspace-state');const shared=result.shared||{},personal=result.personal||{};serverSharedSnapshot=structuredClone(shared);serverPersonalSnapshot=structuredClone(personal);state={...defaultState,...shared,...personal,role:user.role,profile:{...defaultState.profile,...(user.profile||{}),...(personal.profile||{}),name:user.name,email:user.email},route:user.role==='Admin'?'Dashboard':'Home',pendingRole:user.role};if(user.role==='Admin'){try{const [data,analytics]=await Promise.all([api('/api/users'),api('/api/analytics')]);state.users=(data.users||[]).map(u=>({id:u.id,name:u.name,email:u.email,role:u.role,department:u.profile?.department||'',profile:u.profile,experience:Number(u.profile?.experience)||0,score:null,status:u.status,joined:u.createdAt}));state.analytics=analytics;}catch(e){toast(e.message);}}else if(user.role==='Trainer'){try{const data=await api('/api/trainees');state.users=(data.trainees||[]).map(u=>({...u,role:'Trainee'}));}catch(e){toast(e.message);}}if(user.role==='Trainee'){try{state.trainers=(await api('/api/trainers')).trainers||[];state.proofs=(await api('/api/skill-proofs')).proofs||[];}catch(error){toast(error.message);}}else if(user.role==='Trainer'){try{state.skillProofs=(await api('/api/skill-proofs')).proofs||[];}catch(error){toast(error.message);}}state.copilotOpen=false;copilotWelcomeOpen=true;copilotWelcomeMinimized=false;copilotVoiceConversation=false;saveState();render();setTimeout(()=>speakCopilot(copilotWelcomeSpeech()),600);}
function loadState(){try{const saved=JSON.parse(localStorage.getItem('nexora-demo-state')||'{}'),loaded={...defaultState,...saved};loaded.pendingRole=saved.role||saved.pendingRole||null;loaded.role=null;loaded.route='Onboarding';loaded.onboardingSeen=false;return loaded;}catch{return {...defaultState};}}
function saveState(){localStorage.setItem('nexora-demo-state',JSON.stringify(state));if(!currentUser)return;clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{const allShared={courses:state.courses,announcements:state.announcements,feedbacks:state.feedbacks,resources:state.resources,questionnaires:state.questionnaires,competencyMapping:state.competencyMapping,organizationCompetencies:state.organizationCompetencies},allPersonal={};for(const key of ['competencies','completedModules','missionComplete','assessmentDone','assessmentCorrect','assessmentSkipped','assessmentIncorrect','assessmentScore','missionScore','missionResponse','proofSkill','proofSubmitted','courseProgress','enrolled','events','reminders','questionnaireSubmissions','assessmentAnswers','selectedCourse','courseSearch','userRoleFilter'])if(key in state)allPersonal[key]=state[key];const changed=(next,previous)=>Object.fromEntries(Object.entries(next).filter(([key,value])=>JSON.stringify(value)!==JSON.stringify(previous[key])));const shared=changed(allShared,serverSharedSnapshot),personal=changed(allPersonal,serverPersonalSnapshot);if(!Object.keys(shared).length&&!Object.keys(personal).length)return;try{await api('/api/workspace-state',{method:'PUT',body:JSON.stringify({shared,personal})});serverSharedSnapshot={...serverSharedSnapshot,...shared};serverPersonalSnapshot={...serverPersonalSnapshot,...personal};}catch(error){toast(`Could not save changes: ${error.message}`);}},250);}
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<span class="ico ${cls}" aria-hidden="true">${icons[name]||'•'}</span>`;
function toast(message){const region=$('#toast-region');if(!region)return;const el=document.createElement('div');el.className='toast';el.innerHTML=`<span class="toast-check">✓</span>${esc(message)}`;region.append(el);setTimeout(()=>el.remove(),3000);}
function go(route){if(state.role&&!routeAccess[state.role]?.has(route)){toast(`This page is not available in the ${state.role.toLowerCase()} workspace.`);return;}if(route==='Assessments'&&state.route!=='Assessments'){assessmentIndex=0;selectedAnswer=-1;assessmentAnswers=[];}if(state.route==='Onboarding'&&route!=='Onboarding')state.onboardingSeen=true;state.route=route;saveState();render();if(route==='Co-pilot'&&state.role==='Trainer')loadQuestionnaireReports();window.scrollTo({top:0,behavior:'smooth'});}
function initials(name='User'){return name.split(' ').map(s=>s[0]).slice(0,2).join('').toUpperCase();}
function avatar(name='User',tone='violet',photo=''){return `<div class="avatar avatar-${tone}${photo?' has-photo':''}">${photo?`<img src="${esc(photo)}" alt="" loading="lazy"/>`:esc(initials(name))}</div>`;}
function field(label,placeholder='',type='text'){return `<label class="field"><span>${esc(label)}</span><input type="${type}" placeholder="${esc(placeholder)}" /></label>`;}
function progress(value,color='violet'){return `<div class="progress"><span style="width:${Math.max(0,Math.min(100,value))}%;--bar:${color}"></span></div>`;}
function scoreRing(value,label='Capability Score'){return `<div class="score-ring-wrap"><div class="score-ring" style="--score:${value}%"><span>${value}%</span></div><div><div class="eyebrow">${esc(label)}</div><div class="score-caption">${value>=70?'Strong momentum':'Growing steadily'}</div></div></div>`;}
function shell(){const role=state.role||'Trainee',nav=navByRole[role]||navByRole.Trainee,referenceHome=state.route==='Home'||state.route==='Dashboard';return `<div class="app-shell ${referenceHome?'reference-home':''}"><aside class="sidebar"><button class="brand" data-go="Home"><span class="brand-mark"><i></i><i></i><i></i></span><span>NEXORA<small>LEARN · PRACTICE · GROW</small></span></button><div class="org-switch"><span class="org-dot"></span><span>${esc(state.profile.organization||state.profile.department||'Workspace')} · Nexora</span><span class="chev">⌄</span></div><div class="side-label">${role} workspace</div><nav class="side-nav">${nav.map(([label,ic])=>`<button class="nav-item ${state.route===label?'active':''}" aria-label="${esc(label)}" title="${esc(label)}" data-go="${esc(label)}">${icon(ic)}<span>${esc(label)}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><span class="help-spark">✦</span><b>Ready to grow?</b><p>Your next step is waiting.</p><button data-go="${role==='Trainee'?'Learning Path':'Performance'}">Explore learning <span>→</span></button></div><button class="nav-item" data-go="Profile & Settings">${icon('settings')}<span>Settings</span></button><button class="profile-switch" data-go="Profile & Settings">${avatar(state.profile.name,'violet',state.profile.photo)}<span><b>${esc(state.profile.name)}</b><small>${esc(role)}</small></span><span class="dots">···</span></button></div></aside><main class="main-area"><header class="topbar"><button class="mobile-menu" aria-label="Open navigation" title="Open navigation" data-action="toggle-menu">☰</button><div class="breadcrumb">Workspace <span>/</span> <b>${esc(state.route)}</b></div><div class="top-actions"><div class="demo-badge"><span></span> ${currentUser?'LIVE WORKSPACE':'PREVIEW'}</div><button class="icon-button" title="Announcements" data-go="Announcements">${icon('bell')}<i class="notification-dot"></i></button><button class="top-avatar" data-go="Profile & Settings">${avatar(state.profile.name,'violet',state.profile.photo)}</button></div></header><div class="content" id="content">${page()}</div><nav class="mobile-nav">${mobileNavByRole[role].map(([label,ic])=>`<button class="${state.route===label?'active':''}" data-go="${label}">${icon(ic)}<span>${label==='Profile & Settings'?'Profile':label}</span></button>`).join('')}</nav><button class="copilot-fab ${copilotWelcomeMinimized?'copilot-fab-minimized':''}" data-action="${copilotWelcomeMinimized?'restore-copilot-welcome':'open-copilot'}" aria-label="${copilotWelcomeMinimized?'Reopen Nexora AI welcome':'Open Nexora Co-pilot'}"><span>✦</span><b>${copilotWelcomeMinimized?'Nexora AI':'Ask Nexora'}</b></button></main></div><div class="modal-backdrop" id="modal-root" hidden></div>`;}
function loginLayout(back=''){const role=state.pendingRole||'Trainee',admin=role==='Admin';return `<main class="login-reference"><header class="login-header"><button class="login-wordmark" data-go="Welcome">NEXORA</button><span>Learn <i>·</i> Practice <i>·</i> Prove <i>·</i> Grow</span></header><div class="login-scene"><div class="window-frame"><div class="window-view"></div><i></i><i></i></div><div class="scene-caption"><b>—</b><p>A focused<br/>mind builds<br/>a brighter<br/>tomorrow.</p></div></div><section class="login-copy"><div class="quote-line"><h1><strong>Discipline<br/>today,</strong><br/><span>builds the expert<br/>you become<br/>tomorrow.</span></h1></div><p class="login-intro">Sign in to continue<br/>your learning journey.</p><form id="login-form" class="login-card"><div class="login-tabs"><button type="button" class="login-tab ${admin?'':'active'}" data-action="login-role" data-role="Trainee">Student / Employee</button><button type="button" class="login-tab ${admin?'active':''}" data-action="login-role" data-role="Admin">Admin</button></div><label class="login-field"><span class="field-icon">✉</span><input name="email" type="text" placeholder="Email or Employee ID" aria-label="Email or Employee ID" autocomplete="username"/><span class="field-spacer"></span></label><label class="login-field"><span class="field-icon">♙</span><input name="password" type="password" placeholder="Password" aria-label="Password" autocomplete="current-password"/><button type="button" class="password-eye" data-action="toggle-password" aria-label="Show password">◎</button></label><div class="login-options"><label class="remember-option"><input type="checkbox"/> <span>Remember me</span></label><button type="button" class="text-button" data-action="forgot">Forgot Password?</button></div><button class="login-submit" type="submit">Sign In <span>→</span></button><p class="login-create">New to Nexora? <button type="button" data-action="create-account">Register as ${esc(role)}</button></p></form><div class="learner-proof"><p>Your account keeps its own profile and learning progress.</p></div></section>${back?`<button class="login-back" data-go="${back}">← Back</button>`:''}</main>`;}
