function onboardingPage(){return `<main class="onboarding-screen"><div class="onboarding-backdrop" aria-hidden="true"></div><header class="onboarding-header"><button class="onboarding-skip" data-go="Welcome">Skip <span aria-hidden="true">›</span></button></header><section class="onboarding-content"><div class="onboarding-brand" aria-label="Nexora"><span>NEX</span><i aria-hidden="true"></i><span>RA</span></div><p class="onboarding-motto">LEARN <i>·</i> PRACTICE <i>·</i> PROVE <i>·</i> GROW</p><p class="onboarding-description">A focused platform for real skills<br class="desktop-break"/> and measurable capability.</p><div class="onboarding-pillars"><article><span class="onboarding-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M24 13c-5-5-12-5-18-2v25c6-3 13-3 18 2m0-25c5-5 12-5 18-2v25c-6-3-13-3-18 2m0-25v25"/></svg></span><b>Learn</b><small>Structured<br/>courses</small></article><article><span class="onboarding-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M9 35h7V25H9zm12 0h7V17h-7zm12 0h7V9h-7z"/></svg></span><b>Practice</b><small>Hands-on<br/>assessments</small></article><article><span class="onboarding-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="m24 6 15 6v11c0 10-6 16-15 20C15 39 9 33 9 23V12zm-7 17 5 5 10-11"/></svg></span><b>Prove</b><small>Earn<br/>certificates</small></article><article><span class="onboarding-icon"><svg viewBox="0 0 48 48" aria-hidden="true"><path d="M24 40V24m0 5c0-12-7-17-16-17 0 10 4 17 16 17zm0-7c1-10 7-15 16-15 0 9-5 15-16 15z"/></svg></span><b>Grow</b><small>Unlock new<br/>opportunities</small></article></div></section><div class="onboarding-actions"><button class="onboarding-primary" data-go="Welcome">Get Started <span aria-hidden="true">→</span></button><button class="onboarding-secondary" data-go="Role Selection">Explore Platform <span aria-hidden="true">→</span></button></div></main>`;}
function rolePick(){return `<main class="role-reference"><header class="role-top"><button class="role-back" data-go="Welcome" aria-label="Back">←</button><div class="onboarding-progress"><i class="active"></i><i></i><i></i><i></i></div><button class="role-skip" data-action="choose-role" data-role="Trainee">Skip</button></header><section class="role-hero"><span class="role-wordmark">N E X O R A</span><h1>Choose<br/>Your <em>Role</em></h1><p>Get a personalized experience<br/>tailored to your goals.</p><div class="role-motto">LEARN · PRACTICE · PROVE · GROW</div><div class="role-arch"><span class="arch-glow"></span><span class="bonsai-pot"></span><span class="bonsai-trunk"></span><span class="bonsai-crown">✦</span></div></section><section class="role-cards">${[['Trainee','Learn · Practice · Grow','Build your skills, take assessments and get job ready.',['Access structured learning','Take assessments & track progress','Get certified & become job ready'],'Learn','role-trainee'],['Trainer','Create · Teach · Guide','Create courses, take live sessions and mentor learners.',['Create and publish courses','Take live sessions','Build your community'],'My Courses','role-trainer'],['Admin','Manage · Track · Empower','Manage users, monitor progress and drive learning excellence.',['Manage users and roles','Track platform performance','Ensure quality and compliance'],'Dashboard','role-admin']].map(([name,tagline,desc,features,goTo,cls])=>`<button class="role-showcase ${cls}" data-action="choose-role" data-role="${name}"><span class="role-image"></span><span class="role-shade"></span><span class="role-content"><span class="role-icon-box">${name==='Trainee'?'⌑':name==='Trainer'?'♧':'▦'}</span><span class="role-tagline">${tagline}</span><strong>${name}</strong><small>${desc}</small><span class="role-features">${features.map((f,i)=>`<i><b>${['♧','▥','♙'][i]}</b>${f}</i>`).join('')}</span></span><span class="role-next">→</span></button>`).join('')}</section></main>`;}
