function page(){if(!state.role)return state.route==='Onboarding'?onboardingPage():state.route==='Welcome'?welcome():state.route==='Login / Sign Up'?authPage():state.route==='Admin Login'?authPage():state.route==='Registration'?registrationPage():rolePick();const pages={'Home':homePage,'Dashboard':homePage,'My Learning':myLearningPage,'Courses':coursesPage,'My Courses':trainerCourses,'Create Course':createCourse,'Assessments':assessmentPage,'Assessment Result':assessmentResult,'Mission Lab':missionPage,'Mission Interface':missionInterface,'Mission Result':missionResult,'Capability DNA':capabilityPage,'Competency Gaps':gapsPage,'Learning Path':learningPath,'Skill Proof':skillProof,'Capability Passport':passportPage,'Capability Replay':replayPage,'Trainees':traineesPage,'Performance':performancePage,'Competencies':competencyPage,'Competency Mapping':mappingPage,'Organization Competency':orgCompetencyPage,'Analytics':analyticsPage,'Users':usersPage,'Approvals':approvalsPage,'Trainers':trainersPage,'Announcements':announcementsPage,'Trainer Library':libraryPage,'Content':libraryPage,'Profile & Settings':profilePage,'Co-pilot':profilePage};if(state.route==='Co-pilot')return state.role==='Trainer'?questionnairePage():profilePage();return (pages[state.route]||homePage)();}
