trainerMatchData = function trainerMatchData(subject='',focus=''){
  const required=[subject,focus].filter(Boolean).map(value=>value.toLowerCase()),trainers=state.trainers||[];
  return trainers.map(user=>{const profile=user.profile||{},skills=[...(profile.skills||[]),...(profile.competencies||[]),profile.specialization||''].map(value=>String(value).toLowerCase()).filter(Boolean);const matched=required.filter(term=>skills.some(skill=>skill.includes(term)||term.includes(skill))).length;return {...user,profile:{...profile,competencies:profile.competencies||{}},required,match:required.length?Math.round(matched/required.length*100):0,competencyScore:required.length?Math.round(matched/required.length*100):0};}).sort((a,b)=>b.match-a.match);
}
